import sys

def main():
    line = sys.stdin.readline().strip()
    if not line:
        print(-1)
        return
    arr = list(map(int, line.split()))
    n = len(arr)
    if n == 0:
        print(-1)
        return
    if n == 1:
        print(0)
        return

    left, right = 0, n - 1
    while left < right:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        if arr[mid1] < arr[mid2]:
            left = mid1 + 1
        else:
            right = mid2 - 1

    print(left)

if __name__ == "__main__":
    main()
